if (tw.local.error != null && !!tw.local.error.errorText) {
	tw.local.errorMSG = tw.local.error.errorText;
}else if ( tw.system.error != null) {
	tw.local.errorMSG = String(tw.system.error.getAttribute("type")) +","+ String(tw.system.error.getElementByTagName("localizedMessage").item(0).getText());
	tw.local.error = new tw.object.AjaxError();
}else{
	tw.local.error = new tw.object.AjaxError();
}

tw.local.error.errorText = "Error Occured<br> Service Name : "+tw.system.serviceFlow.name+"<br> Error Message : "+tw.local.errorMSG;
tw.local.message= tw.local.error.errorText;
