scripts.script:
if (tw.local.results[0].rows[0].data[0] == null) {
	tw.local.haveRunningRequest = false;
	tw.local.isvalid = true;
	
}
else{
	tw.local.haveRunningRequest = true;
	tw.local.isvalid = false;
	tw.local.massege = "this request number has Running Request";
	
}

if (tw.local.IDCRequest.IDCRequestType.englishdescription =="IDC Completion" ) {

	if (tw.local.parentIDC.IDCRequestStage =="Final") {
		tw.local.massege = "can not make IDC Completion request for request its stage Final";
		tw.local.isvalid = false;
	}
	else{
		tw.local.isvalid = true;
	}
	
}else if (tw.local.IDCRequest.IDCRequestType.englishdescription =="IDC Payment" ) {

	if (tw.local.parentIDC.IDCRequestStage != "Final") {
		tw.local.massege = "can not make IDC Payment request for request its stage initial";
		tw.local.isvalid = false;
	}
	else if(tw.local.parentIDC.paymentTerms.englishdescription == "Sight"){
		tw.local.massege = "can not make IDC Payment request for request its payment Terms Sight";
		tw.local.isvalid = false;
	}else if(tw.local.parentIDC.financialDetails.amtSight > 0 ){
		tw.local.massege = "can not make IDC Payment request for request its sight amount more than 0";
		tw.local.isvalid = false;
	}
	else{
		tw.local.isvalid = true;
	}
}
else{
	tw.local.isvalid = true;
}

tw.local.sql = "SELECT max(ID) FROM BPM.IDC_REQUEST_DETAILS WHERE REQUEST_NUMBER like ? AND REQUEST_STATUS != 'Completed' AND REQUEST_STATUS != 'Terminated' AND REQUEST_STATUS != 'Canceled'";
tw.local.parameters = new tw.object.listOf.SQLParameter();
tw.local.parameters[0]  = new tw.object.SQLParameter();
tw.local.parameters[0].value = tw.local.requestNumber+"%";

tw.local.isTotalyPaid = false;
if (tw.local.SCQueryBCContractRes.OutstandingAmount != "" && tw.local.SCQueryBCContractRes.OutstandingAmount!=null && tw.local.SCQueryBCContractRes.OutstandingAmount != undefined) {
	tw.local.idcContract.outstandingAmount = parseFloat(tw.local.SCQueryBCContractRes.OutstandingAmount);
}

if (tw.local.idcContract.outstandingAmount == 0) {
	tw.local.isvalid = false;
	tw.local.isTotalyPaid = true;
	tw.local.massege = "this request is totally paid";
}else{
	tw.local.isvalid = true;

 	tw.local.idcContract.IDCProduct.code = tw.local.SCQueryBCContractRes.ProductCode;
 	tw.local.idcContract.IDCProduct.englishdescription = tw.local.SCQueryBCContractRes.ProductDesc;
	 
