function stringToList(string) {
	var stringList = new tw.object.listOf.String();
	stringList[0] = string;
	return stringList;
}

function floatToStringList(float) {
	var stringList = new tw.object.listOf.String();
	stringList[0] = "" + float;
	return stringList;
}

function booleanToStringList(boolean) {
	var stringList = new tw.object.listOf.String();
	if (boolean)
		stringList[0] = "نعم"
	else
		stringList[0] = "لا"
	return stringList;
}

function formatDate(date) {
	date.setHours(date.getHours() + 2);
	var d = new Date(date),
		day = '' + (d.getDate()),
		month = '' + (d.getMonth() + 1),
		year = d.getFullYear();

	if (month.length < 2)
		month = '0' + month;
	if (day.length < 2)
		day = '0' + day;

	return [day, month, year].join('/');
}

tw.local.request = new tw.object.DocumentGenerationRequest();
tw.local.request.templates = new tw.object.listOf.RequestTemplatePojo();
//tw.local.request.templates[0] = new tw.object.RequestTemplatePojo();

tw.local.request.appName = "ODC create/Amend";
tw.local.request.purposeCode = new tw.object.listOf.String();
tw.local.request.purposeCode[0] = "PUR1";

tw.local.request.programCode = "PROG1";
//"PROG1";

tw.local.request.secure = true;

tw.local.paramsValues = new tw.object.Map();


//---------------------------------------------------
var ecmInfo = new tw.object.EcmDocumentInformation();
ecmInfo.docClassName = "Document";
ecmInfo.docProperties = "";
ecmInfo.folderId = tw.local.docGenTempFolder.path;

if (tw.local.generationStatus == "Generate") {
	var title = "";
}
else {
	if (tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetterOption.value == "other") {
		var title = tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetterTitle;
	}
	else {
		var title = tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetterOption.value;
	}
}
//var title = tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetterOption.value + tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetterTitle;
tw.local.paramsValues.put("Title001", stringToList(title));
var date = new tw.object.Date();
tw.local.paramsValues.put("Date001", stringToList(formatDate(date)));
var swiftCode = "NBEGEGCX" + tw.local.odcRequest.FinancialDetailsFO.executionHub.value;

tw.local.paramsValues.put("Swift001", stringToList(swiftCode));
tw.local.paramsValues.put("Int001", stringToList(tw.local.odcRequest.ImporterDetails.bank));
tw.local.paramsValues.put("Int002", stringToList(tw.local.odcRequest.ImporterDetails.bankAddress));
