tw.local.paramsValues.put("Int004", stringToList(tw.local.odcRequest.ImporterDetails.BICCode));
tw.local.paramsValues.put("Int005", stringToList(tw.local.odcRequest.GeneratedDocumentInfo.customerName));
tw.local.paramsValues.put("Int006", stringToList(tw.local.odcRequest.GeneratedDocumentInfo.customerAddress));
tw.local.paramsValues.put("Int007", stringToList(tw.local.odcRequest.ImporterDetails.importerName));
tw.local.paramsValues.put("Int008", stringToList(tw.local.odcRequest.ImporterDetails.importerAddress));
tw.local.paramsValues.put("Int009", stringToList(tw.local.odcRequest.ImporterDetails.importerPhoneNo));
tw.local.paramsValues.put("Int010", floatToStringList(tw.local.odcRequest.FinancialDetailsFO.collectableAmount));
tw.local.paramsValues.put("Int011", floatToStringList(tw.local.odcRequest.FinancialDetailsFO.ourCharges));
var claimedAmount = tw.local.odcRequest.FinancialDetailsFO.collectableAmount + tw.local.odcRequest.FinancialDetailsFO.ourCharges;
tw.local.paramsValues.put("Int012", floatToStringList(claimedAmount));
tw.local.paramsValues.put("Int013", stringToList(tw.local.odcRequest.FinancialDetailsBR.currency.name));
if (tw.local.odcRequest.BasicDetails.paymentTerms.name == "001") {
	tw.local.paramsValues.put("Int014", stringToList("Sight"));
}
else {
	tw.local.paramsValues.put("Int014", stringToList(formatDate(tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[0].date)));
}
tw.local.paramsValues.put("Int015", stringToList(tw.local.odcRequest.FinancialDetailsFO.referenceNo));

var deliveryTerms = new tw.object.listOf.String();
for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.deliveryTerms.listLength; i++) {
	deliveryTerms[i] = tw.local.odcRequest.GeneratedDocumentInfo.deliveryTerms[i];
}
if (tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra.listLength != 0) {
	for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra.listLength; i++) {
