	}
}

tw.local.paramsValues.put("Int016", deliveryTerms);

var paymentInstructions = new tw.object.listOf.String();
for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructions.listLength; i++) {
	paymentInstructions[i] = tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructions[i];
}
var length = paymentInstructions.length;
if (tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra.listLength != 0) {
	for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra.listLength; i++) {
		paymentInstructions[paymentInstructions.length] = tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra[i];
	}
}

tw.local.paramsValues.put("Int017", paymentInstructions);

var instructions = new tw.object.listOf.String();
for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.Instructions.listLength; i++) {
	instructions[i] = tw.local.odcRequest.GeneratedDocumentInfo.Instructions[i];
}
if (tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra.listLength != 0) {
	for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra.listLength; i++) {
		instructions[instructions.length] = tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra[i];
	}
}
tw.local.paramsValues.put("Int018", instructions);

var specialInstructions = new tw.object.listOf.String();
for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.specialInstructions.listLength; i++) {
	specialInstructions[i] = tw.local.odcRequest.GeneratedDocumentInfo.specialInstructions[i];
}
if (tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra.listLength != 0) {
	for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra.listLength; i++) {
		specialInstructions[specialInstructions.length] = tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra[i];
	}
}

tw.local.paramsValues.put("Int019", specialInstructions);

////////////////////////////////////////////////////////////////////////////////
var documentNames = new tw.object.listOf.String();
var noOfCopies = new tw.object.listOf.String();
var noOfOriginals = new tw.object.listOf.String();
var docsCount =0;
for (var i = 0; i < tw.local.odcRequest.attachmentDetails.attachment.listLength; i++) {
	if (!!tw.local.odcRequest.attachmentDetails.attachment[i].numOfOriginals || !!tw.local.odcRequest.attachmentDetails.attachment[i].numOfCopies) {
		if (tw.local.odcRequest.attachmentDetails.attachment[i].name == "" || tw.local.odcRequest.attachmentDetails.attachment[i].name == null) {
			documentNames[docsCount] = "";
		}
		else {
			documentNames[docsCount] = tw.local.odcRequest.attachmentDetails.attachment[i].name;
		}
		if (tw.local.odcRequest.attachmentDetails.attachment[i].numOfOriginals == "" || tw.local.odcRequest.attachmentDetails.attachment[i].numOfOriginals == null) {
			noOfOriginals[docsCount] = "";
		}
		else {
			noOfOriginals[docsCount] = tw.local.odcRequest.attachmentDetails.attachment[i].numOfOriginals + "";
		}
		if (tw.local.odcRequest.attachmentDetails.attachment[i].numOfCopies == "" || tw.local.odcRequest.attachmentDetails.attachment[i].numOfCopies == null) {
			noOfCopies[docsCount] = "";
		}
		else {
			noOfCopies[docsCount] = tw.local.odcRequest.attachmentDetails.attachment[i].numOfCopies + "";
		}
		docsCount++;

	}
//	else{
//		continue;
//	}
}
if(docsCount>0){
	tw.local.paramsValues.put("intr001", documentNames);
	tw.local.paramsValues.put("intr002", noOfOriginals);
	tw.local.paramsValues.put("intr003", noOfCopies);
}



//tw.local.paramsValues.put("intr001",specialInstructions);
//tw.local.paramsValues.put("intr002",specialInstructions);
//tw.local.paramsValues.put("intr003",specialInstructions);

tw.local.request.paramsValues = tw.local.paramsValues;
//--------------------------Generate Docs-------------------
var template = new tw.object.RequestTemplatePojo();
template.secure = true;
template.ecmDocInfo = ecmInfo;
template.templateCode = "ODCRemittanceLetter";
template.generatedDocName = "remittance Letter";
tw.local.request.templates.insertIntoList(tw.local.request.templates.listLength, template);

if(!!tw.local.results){

   for(var i=0;i<tw.local.results[0].rows.listLength;i++){
       for(var j=0 ; j< tw.local.transaction.listLength; j++){
        if( tw.local.results[0].rows[i].data[0] == tw.local.transaction[j].referenceNumber){
           tw.local.transaction[j].existAmount = tw.local.results[0].rows[i].data[1];
           if(tw.local.transaction[j].existAmount == tw.local.transaction[j].transactionAmount)
             tw.local.transaction.removeIndex(j);
           break;
            }
        }
       } 
}

tw.local.transaction = new tw.object.listOf.FCTransactions();

if(tw.local.MWtransactions != null && tw.local.MWtransactions.listLength != 0)
{
	for(var i=0;i<tw.local.MWtransactions.listLength;i++)
	{       
		tw.local.transaction[i] = new tw.object.FCTransactions();
