tw.local.sqlStatements[j] = new tw.object.SQLStatement();

if(tw.local.parentODCRequest.requestType.value == amend || tw.local.parentODCRequest.requestType.value == recreate  ){
  tw.local.sqlStatements[j].sql="SELECT * FROM ARCHUSR.ODC_REQUESTINFO WHERE ID = (SELECT max(ID) FROM ARCHUSR.ODC_REQUESTINFO WHERE  PARENTREQUESTNO = ? AND (REQUESTTYPE = '"+amend+"' OR REQUESTTYPE = '"+recreate+"' OR REQUESTTYPE = '"+create+"') AND REQUESTSTATE = '"+final+"'  AND REQUESTSTATUS='"+completed+"')";
  if(tw.local.parentODCRequest.requestType.value == amend ) 
    tw.local.sqlStatements[j].sql+= " AND OUTSTANDINGAMOUNT > 0;";
   tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
   paramInit(tw.local.parentODCRequest.parentRequestNo);
}

else if(tw.local.parentODCRequest.requestType.value == collection || tw.local.parentODCRequest.requestType.value == closure || tw.local.parentODCRequest.requestType.value == reversal ){

  
  if(tw.local.parentODCRequest.requestType.value == collection){
      tw.local.sqlStatements[j].sql="SELECT ID, liqAmount, liqCurrency, isLiquidated , "
      +"LIQDEBITVALUEDATE, LIQCREDITVALUEDATE, LIQDEBITACCNUM, LIQCREDITACCOUNTCLASS, LIQCREDITBRANCHCODE, LIQCREDITBALANCESIGN, LIQCREDITACCOUNTCURRENCY, LIQCREDITACCOUNTBALANCE, STANDARDEXRATE, NEGOTIATEDEXRATE,LIQCREDITAMOUNTINACCOUNT, OUTSTANDINGAMOUNT"
      +" FROM ARCHUSR.ODC_REQUESTINFO WHERE ID = (SELECT max(ID) FROM ARCHUSR.ODC_REQUESTINFO WHERE  PARENTREQUESTNO = ? AND REQUESTTYPE = '"+collection+"'   AND REQUESTSTATE = '"+collected+"' AND REQUESTSTATUS='"+completed+"')";
      tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
      paramInit(tw.local.parentODCRequest.parentRequestNo);
  
  }
  else if (tw.local.parentODCRequest.requestType.value == closure){
       tw.local.sqlStatements[j].sql="SELECT ID, CLOSUREREASON FROM ARCHUSR.ODC_REQUESTINFO WHERE ID = (SELECT max(ID) FROM ARCHUSR.ODC_REQUESTINFO WHERE  PARENTREQUESTNO = ? AND REQUESTTYPE = '"+closure+"'  AND REQUESTSTATE = '"+closed+"' AND REQUESTSTATUS='"+completed+"')";
       tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
       paramInit(tw.local.parentODCRequest.parentRequestNo);
  
  
  }
  else{
       tw.local.sqlStatements[j].sql="SELECT ID, REVERSALREASON FROM ARCHUSR.ODC_REQUESTINFO WHERE ID = (SELECT max(ID) FROM ARCHUSR.ODC_REQUESTINFO WHERE  PARENTREQUESTNO = ? AND REQUESTTYPE = '"+reversal+"'  AND REQUESTSTATE = '"+reversed+"' AND (REQUESTSTATUS='"+completed+"' OR REQUESTSTATUS='"+approved+"' ))";
       tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
       paramInit(tw.local.parentODCRequest.parentRequestNo);
  }
  
  j++;
  i=0;
  // get some of create data
  tw.local.sqlStatements[j] = new tw.object.SQLStatement();
  tw.local.sqlStatements[j].sql="SELECT ID, EXPORTPURPOSE,PAYMENTTERMS,PRODUCTCATEGORY,COMMODITYDESCRIPTION,CIF,CUSTOMERNAME,IMPORTERNAME, MAXIMUMCOLLECTIONDATE, REQUESTCURRENCY, DOCUMENTAMOUNT, ADVANCEAMOUNT,collectionCurrency, standardExRate, negotiatedExRate ,  COLLECTIONACCOUNT, CHARGESACCOUNT,  COUNTRYOFORIGIN,requestNo, requestNature , requestType , requestDate"
   +" FROM ARCHUSR.ODC_REQUESTINFO WHERE ID = (SELECT max(ID) FROM ARCHUSR.ODC_REQUESTINFO WHERE  PARENTREQUESTNO = ? AND (REQUESTTYPE = '"+amend+"' OR REQUESTTYPE = '"+recreate+"' OR REQUESTTYPE = '"+create+"') AND REQUESTSTATE = '"+final+"'  AND REQUESTSTATUS='"+completed+"' ) ";
  
  if(tw.local.parentODCRequest.requestType.value == collection || tw.local.parentODCRequest.requestType.value == closure ) 
      tw.local.sqlStatements[j].sql +=" AND OUTSTANDINGAMOUNT > 0;";
      tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
     paramInit(tw.local.parentODCRequest.parentRequestNo);   

}


else{}

if (tw.local.results[0].rows.listLength == 0) {
      if(tw.local.parentODCRequest.requestType.value == "amend" || tw.local.parentODCRequest.requestType.value == "closure" || tw.local.parentODCRequest.requestType.value == "collection"){
	 tw.local.message = "Request number does not exist or is in another running request or Outstanding amount is not > 0 ";
	}
	else
	 tw.local.message = "Request number does not exist or is in another running request";
	tw.local.isFound = false;
}

else{

      tw.local.isFound = true;
      
      if(tw.local.parentODCRequest.requestType.value == "recreate"){
      
      //There must be no collection done on ODC

         for(var i =0 ; i <tw.local.results[0].rows.listLength; i++){

             if(tw.local.results[0].rows[i].data[3] == "ODC Collection"){
