// Function to retrieve EPV children as a concatenated string
function getEPVChildrenAsString(epv) {
	var resultString = "";

	// Check if epv is an object
	if (epv) {
		// Use Object.keys() to get all keys of the EPV object
		var keys = Object.keys(epv);

		keys.forEach(function (childKey) {
			var childValue = epv[childKey];
			
				// Ensure it's a string value
				resultString += childKey + ": " + childValue + "; ";
			
		});
	} else {
		throw new Error("EPV is not an object or does not have child properties.");
	}
	// Trim the trailing semicolon and space if needed
      return resultString;
}

