scripts.script:
tw.local.isfound = true;
if (tw.local.sqlResults[0].rows.listLength == 0) {
	tw.local.isfound = false;
	tw.local.message = "Faild to retrieve Product Code";
}else{
	tw.local.productCode = tw.local.sqlResults[0].rows[0].data[0];

}

var requestTable = tw.env.DBSchema+".ODC_REQUESTINFO"

tw.local.sql = "SELECT PRODUCTCODE FROM "+requestTable+" WHERE REQUESTNO = ?";

tw.local.parameters = new tw.object.listOf.SQLParameter();
tw.local.parameters[0] = new tw.object.SQLParameter();
tw.local.parameters[0].value = tw.local.requestNO;

var requestNumber = tw.local.results[0].rows[0].data[0];
	// arr is array to store the splitted request number
	var arr = requestNumber.split('-');
	// x var the incremental part of request type 
	var x = parseInt(arr[1]);
if(x == "")
	 tw.local.newRequestId = tw.local.parentRequestNumber+"-01";
else
{	 
	x= x+1;
	
	if(x < 9)
	tw.local.tmpvar = "0"+ x;
	else
	tw.local.tmpvar = x;
	
	
	tw.local.newRequestId = tw.local.parentRequestNumber+'-'+tw.local.tmpvar;
	
}

var requestNumber =  tw.local.results[0].rows[0].data[0];
if(requestNumber.indexOf("-") == -1 )
    tw.local.newRequestId = requestNumber + "-01"; 
else {
    var arr = requestNumber.split('-');
    var incrementalPart =  arr[1];
    
    if(incrementalPart[0] == "0" && parseInt(incrementalPart[1]) <9 ){
     var num = parseInt(incrementalPart[1]) + 1;
     tw.local.newRequestId = arr[0] + "-0" + num; 
     }
    else if (parseInt(incrementalPart[1]) == 9 ){
      var num = parseInt(incrementalPart[1]) + 1;
      tw.local.newRequestId = arr[0] + "-" + num;
    }
   else {
      var num = parseInt(incrementalPart) + 1;
      tw.local.newRequestId = arr[0] + "-" + num;
     }
}

tw.local.sql = "select requestNo from ODC_RequestInfo where PARENTREQUESTNO = ? order by requestNo desc;"

tw.local.parameters = new tw.object.listOf.SQLParameter();
tw.local.parameters[0] = new tw.object.SQLParameter();
tw.local.parameters[0].value = tw.local.parentRequestNumber;

tw.local.searchResult = new tw.object.listOf.searchResult();

if(tw.local.results.listLength > 0)
{
	for( var i=0 ; i < tw.local.results[0].rows.listLength ; i++)
	{
		tw.local.searchResult[i] = new tw.object.searchResult();
		tw.local.searchResult[i].customerNumber  	    = tw.local.results[0].rows[i].data[0];
