	}		
}

if(tw.local.searchCriteria.CIF != null && tw.local.searchCriteria.CIF != ""  ) 
{
	tw.local.sql = "select CIF, CUSTOMERNAME, REQUESTTYPE,REQUESTNO ,REQUESTSTATUS ,substatus , REQUESTDATE , currentStepName , BPMInstanceNumber from ODC_REQUESTINFO   "
	                +"where cif = '"+tw.local.searchCriteria.CIF+"' order by REQUESTNO ;"
}
else if(tw.local.searchCriteria.requestType != null && tw.local.searchCriteria.requestType != "") 
{
	tw.local.sql =  "select CIF, CUSTOMERNAME, REQUESTTYPE,REQUESTNO ,REQUESTSTATUS ,substatus, REQUESTDATE , currentStepName , BPMInstanceNumber from ODC_REQUESTINFO   "
	                +"where REQUESTTYPE = '"+tw.local.searchCriteria.requestType+"' order by REQUESTNO ;"
}
else if(tw.local.searchCriteria.BPMRequestNo != null && tw.local.searchCriteria.BPMRequestNo != "") 
{
	tw.local.sql =  "select CIF, CUSTOMERNAME, REQUESTTYPE,REQUESTNO ,REQUESTSTATUS , substatus ,REQUESTDATE , currentStepName , BPMInstanceNumber from ODC_REQUESTINFO   "
	                +"where BPMInstanceNumber = '"+tw.local.searchCriteria.BPMRequestNo+"'  order by REQUESTNO ;"
}
else if(tw.local.searchCriteria.requestDate != null ) 
{
	tw.local.sql =  "select CIF, CUSTOMERNAME, REQUESTTYPE,REQUESTNO ,REQUESTSTATUS , substatus , REQUESTDATE , currentStepName , BPMInstanceNumber from ODC_REQUESTINFO   "
	               +"where REQUESTDATE = '"+tw.local.searchCriteria.requestDate+"'  order by REQUESTNO ;"
}
else if(tw.local.searchCriteria.requestState != null && tw.local.searchCriteria.requestState != "") 
{
	tw.local.sql =  "select CIF, CUSTOMERNAME, REQUESTTYPE,REQUESTNO ,REQUESTSTATUS ,substatus , REQUESTDATE , currentStepName , BPMInstanceNumber from ODC_REQUESTINFO   "
	               +"where REQUESTSTATUS = '"+tw.local.searchCriteria.requestState+"' order by REQUESTNO ;"
}
else if(tw.local.searchCriteria.invoiceNo != null && tw.local.searchCriteria.invoiceNo != "") 
{

	tw.local.sql =  "select CIF, CUSTOMERNAME, REQUESTTYPE,REQUESTNO ,REQUESTSTATUS , substatus , REQUESTDATE , currentStepName , BPMInstanceNumber from ODC_REQUESTINFO   "
			    +"Inner join ODC_INVOICE on ODC_REQUESTINFO.ID = ODC_INVOICE.REQUESRID where INVOICENO = '"+tw.local.searchCriteria.invoiceNo+"' order by REQUESTNO ;"
}
else if(tw.local.searchCriteria.billOfLading != null && tw.local.searchCriteria.billOfLading != "") 
{
	tw.local.sql = "select CIF, CUSTOMERNAME, REQUESTTYPE,REQUESTNO ,REQUESTSTATUS , substatus ,REQUESTDATE , currentStepName , BPMInstanceNumber from ODC_REQUESTINFO  Inner join ODC_BILLS "+
		    "on ODC_REQUESTINFO.ID = ODC_BILLS.REQUESRID where BILLOFLADINGREF = '"+tw.local.searchCriteria.billOfLading+"' order by REQUESTNO ;"
}

else if(tw.local.searchCriteria.tradeFoRefrenceNo != null && tw.local.searchCriteria.tradeFoRefrenceNo != "") 
{
	tw.local.sql =  "select CIF, CUSTOMERNAME, REQUESTTYPE,REQUESTNO ,REQUESTSTATUS , substatus , REQUESTDATE , currentStepName , BPMInstanceNumber from ODC_REQUESTINFO   "
	+"where TRADEFOREFNO = '"+tw.local.searchCriteria.tradeFoRefrenceNo+"' order by REQUESTNO ;"
}

tw.local.searchResult = new tw.object.listOf.searchResult();

if(tw.local.results.listLength > 0)
{
	for( var i=0 ; i < tw.local.results[0].rows.listLength ; i++)
	{
		tw.local.searchResult[i] = new tw.object.searchResult();
		tw.local.searchResult[i].customerNumber  	    = tw.local.results[0].rows[i].data[0];
		tw.local.searchResult[i].customerName    	    = tw.local.results[0].rows[i].data[1];
		tw.local.searchResult[i].requestType          = tw.local.results[0].rows[i].data[2];
		tw.local.searchResult[i].requestNumber        = tw.local.results[0].rows[i].data[3];
		tw.local.searchResult[i].requestStatus        = tw.local.results[0].rows[i].data[4];
		tw.local.searchResult[i].requestSubstatus     = tw.local.results[0].rows[i].data[5];
		tw.local.searchResult[i].requestDate          = tw.local.results[0].rows[i].data[6];
		
		tw.local.searchResult[i].currentActivityName  = tw.local.results[0].rows[i].data[7];
		tw.local.searchResult[i].bpmInstanceID        = tw.local.results[0].rows[i].data[8];
	
		
	}		
}

