//Create Process - Act01
if( (tw.local.odcRequest.stepLog.step == String(tw.epv.ScreenNames.CACT01)) && (tw.local.odcRequest.stepLog.role == String(tw.epv.userRole.branch)) )
	tw.local.mailTo = String(tw.epv.Mails.branchMkr_Mngr);
else if( (tw.local.odcRequest.stepLog.step == String(tw.epv.ScreenNames.CACT01)) && (tw.local.odcRequest.stepLog.role == String(tw.epv.userRole.hub)) )
